sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.leave-approvals-page {
  max-width: 1280px;
  margin: 0 auto;
  padding: 34px 30px 60px;
  min-height: 100vh;
  background: #f7f9fc;
  color: #0f1b45;
  font-family: Arial, sans-serif;
}

.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.page-header h2 {
  margin: 0 0 6px;
  font-size: 28px;
  font-weight: 700;
  color: #0f1b45;
}

.page-header p {
  margin: 0;
  color: #7d879c;
  font-size: 13px;
}

.request-count {
  background: #fff3dc;
  color: #c97700;
  padding: 10px 16px;
  border-radius: 22px;
  font-size: 13px;
  font-weight: 700;
}

.filter-card {
  background: #ffffff;
  border: 1px solid #e3e8ef;
  border-radius: 14px;
  padding: 18px;
  margin-bottom: 20px;
  display: flex;
  gap: 14px;
  align-items: center;
  box-shadow: 0 3px 12px rgba(15,27,69,.05);
}

.search-box {
  flex: 1;
  position: relative;
}

.search-box span {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
}

.search-box input {
  padding-left: 40px !important;
}

.form-control {
  height: 42px;
  border-radius: 9px;
  border: 1px solid #dfe5ed;
}

.btn-clear {
  height: 42px;
  padding: 0 18px;
  border: 1px solid #dfe5ed;
  border-radius: 9px;
  background: #f8fafc;
  color: #44506a;
  font-weight: 600;
}

.requests-card {
  background: #ffffff;
  border: 1px solid #e2e7ef;
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 4px 14px rgba(15,27,69,.05);
}

.leave-table {
  width: 100%;
  margin: 0;
}

.leave-table thead {
  background: #f5f7fb;
}

.leave-table th {
  padding: 14px !important;
  color: #202c4d;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

.leave-table td {
  padding: 14px !important;
  color: #35415d;
  font-size: 12px;
  vertical-align: middle !important;
  border-top: 1px solid #edf1f5 !important;
}

.leave-table tbody tr:hover {
  background: #f9fbfd;
}

.request-number {
  color: #1769e0;
}

.status-pending {
  display: inline-block;
  padding: 5px 10px;
  border-radius: 14px;
  background: #fff2d9;
  color: #d98500;
  font-size: 10px;
  font-weight: 700;
}

.view-btn {
  display: inline-block;
  padding: 7px 14px;
  background: #0b8793;
  color: #ffffff !important;
  border-radius: 8px;
  text-decoration: none !important;
  font-size: 11px;
  font-weight: 700;
}

.view-btn:hover {
  background: #086f79;
}

.empty-state {
  text-align: center;
  padding: 40px !important;
  color: #8d96a8 !important;
}

@media (max-width: 700px) {
  .page-header {
    display: block;
  }

  .request-count {
    margin-top: 14px;
    display: inline-block;
  }

  .filter-card {
    flex-direction: column;
    align-items: stretch;
  }
}

sp_widget.script:
(function() {

    data.requests = [];

    var gr = new GlideRecord('x_snc_unified_hr_0_leave_request');

    // Only requests waiting for HR approval
    gr.addQuery('status', 'pending_hr');

    gr.orderByDesc('sys_created_on');
    gr.query();

    while (gr.next()) {

        var leave = {};

        leave.sys_id = gr.getUniqueValue();
        leave.number = gr.getDisplayValue('number');
        leave.employee = gr.getDisplayValue('employee');
        leave.leave_type = gr.getDisplayValue('leave_type');
        leave.start_date = gr.getDisplayValue('start_date');
        leave.end_date = gr.getDisplayValue('end_date');
        leave.reason = gr.getDisplayValue('reason');
        leave.status = gr.getDisplayValue('status');

        data.requests.push(leave);
    }

})();
